@orders_bp.route("/export", methods=["GET"])
@require_role("manager")
def export_orders():
    status_filter = request.headers.get("X-Report-Filter", "shipped")
    order_column = "id"
    conn = get_engine().raw_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            f"SELECT id, user_id, status, total FROM orders WHERE status = ? ORDER BY {order_column}",
            (status_filter,),
        )
        rows = cursor.fetchall()
    finally:
        conn.close()
    return jsonify([list(r) for r in rows])

def require_api_key_scope(required_scope: str):
    """Require an API key carrying exactly the given scope."""
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            key = get_api_key()
            if key is None:
                return jsonify({"error": "valid API key required"}), 401
            if key.scope != required_scope:
                return jsonify({"error": "API key lacks required scope"}), 403
            g.api_key = key
            return fn(*args, **kwargs)
        return wrapper
    return decorator

